/** Modules generated by the Vite plugin (src/node/vite/plugin.ts). */

declare module 'virtual:shabd/data' {
  import type { SiteData } from '@himanshoe/shabd/client'
  const data: SiteData
  export default data
}

declare module 'virtual:shabd/routes' {
  import type { PageModule } from '@himanshoe/shabd/client'
  export const routes: Record<string, () => Promise<PageModule>>
}

declare module 'virtual:shabd/blocks' {
  import type { ComponentType } from 'react'
  export const customBlocks: Record<string, ComponentType<Record<string, unknown>>>
}

declare module 'virtual:shabd/mdx-components' {
  import type { ComponentType } from 'react'
  export function useMDXComponents(): Record<string, ComponentType<never>>
}

declare module 'virtual:shabd/fonts' {}

declare module 'virtual:shabd/user-styles' {}

declare module 'virtual:shabd/embedder' {
  /** False when semantic search is off or @huggingface/transformers is not installed. */
  export const available: boolean
  export const pipeline: typeof import('@huggingface/transformers').pipeline | undefined
  export const env: typeof import('@huggingface/transformers').env | undefined
}

declare module 'virtual:shabd/sqlite' {
  /** False unless `features.search.store` is `sqlite` and @sqlite.org/sqlite-wasm is installed. */
  export const available: boolean
  export const init: (() => Promise<unknown>) | undefined
}
